// Scale — Gtk.Scale
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles scale with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { PositionType } from "@/lib/enums"

export interface ScaleProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Adjustment, from Gtk.Range */
  adjustment?: ReactNode

  /** gint, from Gtk.Scale */
  digits?: number

  /** gboolean, from Gtk.Scale */
  drawValue?: boolean

  /** gdouble, from Gtk.Range */
  fillLevel?: number

  /** gboolean, from Gtk.Scale */
  hasOrigin?: boolean

  /** gboolean, from Gtk.Range */
  inverted?: boolean

  /** gboolean, from Gtk.Range */
  restrictToFillLevel?: boolean

  /** gint, from Gtk.Range */
  roundDigits?: number

  /** gboolean, from Gtk.Range */
  showFillLevel?: boolean

  /** PositionType, from Gtk.Scale */
  valuePos?: PositionType
}

export function Scale({ className, children }: ScaleProps) {
  return (
    <div className={cn("p-3", "min-h-2.5", "min-w-2.5", className)}>
      {children}
    </div>
  )
}
